public class WarehouseInfo
{
    public string SelectedWarehouseId { get; set; } = "WH-1";
    public string SelectedWarehouseName { get; set; } = "Warehouse A";

    public static readonly (string Id, string Name)[] AvailableWarehouses =
    [
        ("WH-1", "Warehouse A"),
        ("WH-2", "Warehouse B"),
        ("WH-3", "Warehouse C"),
        ("WH-4", "Warehouse D"),
    ];
}

namespace sv_436e4ef50abb48a1bf2616bd7e6a2cf8.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for a warehouse.
/// Components subscribe to <see cref="OnChange"/> to react when new data arrives.
/// Polling is started/stopped by the dashboard page; the sidebar badge passively
/// receives updates through the same event.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private CancellationTokenSource? _cts;
    private int _lowStockCount;
    private string _warehouseId = "";

    public int LowStockCount => _lowStockCount;

    public event Action? OnChange;

    public async Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query
        await Task.Delay(50);
        return Random.Shared.Next(0, 16);
    }

    /// <summary>
    /// Starts polling every 10 seconds. Safe to call multiple times —
    /// previous polling is cancelled first.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        StopPolling();
        _warehouseId = warehouseId;
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    public void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    /// <summary>
    /// Immediately fetches the latest count and notifies subscribers.
    /// Called when the warehouse changes so the UI refreshes without
    /// waiting for the next poll tick.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _warehouseId = warehouseId;
        _lowStockCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        // Fetch immediately on start
        await FetchAndNotifyAsync();

        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await FetchAndNotifyAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when polling is stopped
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        _lowStockCount = await GetLowStockCountAsync(_warehouseId);
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        StopPolling();
    }
}

