using Microsoft.AspNetCore.Components;
using sv_436e4ef50abb48a1bf2616bd7e6a2cf8.Components;
using sv_436e4ef50abb48a1bf2616bd7e6a2cf8.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Scoped so each circuit (user) gets its own instance
builder.Services.AddScoped<InventoryAlertService>();

// CascadingValueSource crosses render-mode boundaries, so interactive components
// inside a static layout can still receive the current warehouse selection.
builder.Services.AddCascadingValue(sp =>
{
    var info = new WarehouseInfo();
    return new CascadingValueSource<WarehouseInfo>(info, isFixed: false);
});

arguments.file_text:
@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@inject InventoryAlertService AlertService
@using sv_436e4ef50abb48a1bf2616bd7e6a2cf8.Services

<select class="form-select form-select-sm w-auto"
        value="@_selectedId"
        @onchange="OnWarehouseChanged">
    @foreach (var (id, name) in WarehouseInfo.AvailableWarehouses)
    {
        <option value="@id">@name</option>
    }
</select>

@code {
    private string _selectedId = "WH-1";

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-1";

        var match = WarehouseInfo.AvailableWarehouses
            .FirstOrDefault(w => w.Id == _selectedId);

        var info = new WarehouseInfo
        {
            SelectedWarehouseId = _selectedId,
            SelectedWarehouseName = match.Name ?? "Unknown"
        };

        // Push the new value to every [CascadingParameter] subscriber
        await WarehouseSource.NotifyChangedAsync(info);

        // Immediately refresh alert data for the new warehouse
        await AlertService.RefreshAsync(_selectedId);
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_436e4ef50abb48a1bf2616bd7e6a2cf8.Services

@if (AlertService.LowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.LowStockCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Wrap in InvokeAsync because the event may fire from the
        // PeriodicTimer background thread, outside the sync context.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

