@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_436e4ef50abb48a1bf2616bd7e6a2cf8.Services

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@(_warehouse?.SelectedWarehouseName ?? "None")</p>
                <p class="text-muted">@(_warehouse?.SelectedWarehouseId)</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-1 @(AlertService.LowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.LowStockCount
                </p>
                <p class="text-muted">Items below minimum level</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text fs-4 text-success">● Active</p>
                <p class="text-muted">Refreshes every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? _warehouse { get; set; }

    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;

        // Start polling for the currently selected warehouse
        AlertService.StartPolling(_warehouse?.SelectedWarehouseId ?? "WH-1");
    }

    protected override void OnParametersSet()
    {
        // When the cascading warehouse value changes, restart polling
        // for the new warehouse so data stays in sync.
        if (_warehouse is not null)
        {
            AlertService.StartPolling(_warehouse.SelectedWarehouseId);
        }
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        AlertService.StopPolling();
    }
}

